draw((-2.5,.9)--(-1.5,.9),EndArrow);
import solids; import three; currentprojection = orthographic(5,0,2);
revolution c = cylinder((0,0,0), 1, 2);
draw((0,-1,2)--(0,1,2)); label("14",((0,-1,2)--(0,1,2)),N); label("14",(0,1,1),E);
draw(c,black);
